mapper.select:
SELECT banner_id::TEXT AS row_id, title, description, btn1_label, btn1_url, btn2_label, btn2_url, start_dt, end_dt, sort_no, use_yn, (SELECT r.file_id FROM file_ref r JOIN file tf ON tf.file_id = r.file_id AND tf.use_yn = 'Y' WHERE r.map_key = banner.banner_id AND r.file_type = 'BANNER' ORDER BY r.sort_no LIMIT 1) AS file_id FROM banner WHERE use_yn = 'Y'
AND title LIKE '%' || #{filterKeyword} || '%'
ORDER BY sort_no, banner_id LIMIT #{pageSize} OFFSET #{offset}
